-- calc_individuals_name
-- Field: Individuals.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_individuals_name(p_individual_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(given_name, '') FROM individuals WHERE individual_id = p_individual_id), ' ', (SELECT NULLIF(family_name, '') FROM individuals WHERE individual_id = p_individual_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_individuals_slug
-- Field: Individuals.Slug
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_individuals_slug(p_individual_id TEXT)
RETURNS TEXT AS $$
  SELECT (REPLACE(LOWER(CONCAT((SELECT NULLIF(family_name, '') FROM individuals WHERE individual_id = p_individual_id), '-', (SELECT NULLIF(given_name, '') FROM individuals WHERE individual_id = p_individual_id))), ' ', '-'))::text;
$$ LANGUAGE sql STABLE;

-- calc_individuals_relative_path
-- Field: Individuals.RelativePath
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_individuals_relative_path(p_individual_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT('/intake/new-patient/', calc_individuals_slug(p_individual_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_individuals_federated_dataset_node_label
-- Field: Individuals.FederatedDatasetNodeLabel
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_individuals_federated_dataset_node_label(p_individual_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN (SELECT NULLIF(federated_dataset, '') FROM individuals WHERE individual_id = p_individual_id) IS NULL THEN ('')::text ELSE (((SELECT node_label FROM federated_datasets WHERE federated_dataset_id = ((SELECT NULLIF(federated_dataset, '') FROM individuals WHERE individual_id = p_individual_id))::text)))::text END)::text;
$$ LANGUAGE sql STABLE;

