CREATE VIEW vw_tissues WITH (security_invoker = ON) AS
SELECT
  t.tissue_id,                                                                  -- Stable identifier for each tissue type.
  t.tissue_label,                                                               -- Human-readable tissue name (blood, gut, synovium, skin, brain).
  calc_tissues_name(t.tissue_id) AS name,                                       -- Display label for the tissue.
  calc_tissues_relative_path(t.tissue_id) AS relative_path,                     -- Canonical path to this Tissue page: /tissues/<slug-or-id>.
  calc_tissues_count_of_omics_assays(t.tissue_id) AS count_of_omics_assays,     -- Number of omics assays performed on this tissue.
  t.omics_assays                                                                -- Omics assays performed on this tissue.
FROM tissues t;

-- ----------------------------------------------------------------------------
-- vw_omics_modalities: Registry of omics assay modalities: RNA-seq, ATAC-seq, proteomics, metabolomics, methylomes, chromatin-conformation, immune-receptor repertoires, microbiomes, and long-read genomes.
-- Combines base table columns with calculated/lookup/aggregation fields.
