CREATE VIEW vw_omics_modalities WITH (security_invoker = ON) AS
SELECT
  t.omics_modality_id,                                                          -- Stable identifier for each omics modality.
  t.modality_label,                                                             -- Human-readable modality name.
  t.is_single_cell,                                                             -- True for single-cell or spatial assays resolving cellular states.
  calc_omics_modalities_name(t.omics_modality_id) AS name,                      -- Display label for the omics modality.
  calc_omics_modalities_relative_path(t.omics_modality_id) AS relative_path,    -- Canonical path to this OmicsModalitie page: /omics-modalities/<slug-or-id>.
  calc_omics_modalities_count_of_omics_assays(t.omics_modality_id) AS count_of_omics_assays,-- Count of assays using this modality.
  t.omics_assays                                                                -- Assays of this modality.
