  t.type_label,                                                                 -- Human-readable variant mechanism label.
  t.is_rare_variant_class,                                                      -- True when this type contributes to rare-variant burden scoring.
  calc_variant_types_name(t.variant_type_id) AS name,                           -- Display label for variant type.
  calc_variant_types_relative_path(t.variant_type_id) AS relative_path,         -- Canonical path to this VariantType page: /variant-types/<slug-or-id>.
  calc_variant_types_count_of_genomic_variants(t.variant_type_id) AS count_of_genomic_variants,-- Variants classified under this type.
